mapper.select:
        SELECT
        distinct r.*
        FROM
        contract_reimbursement AS r
        LEFT JOIN
        contract_reimbursement_detail AS rd
        ON r.id = rd.reimbursement_id
        WHERE
        r.bool_delete_enum = 0
        AND rd.bool_delete_enum = 0

        
            and rd.expense_type_id = #{type}
        

        
            and r.create_time >= #{startDate}
        

        
            and r.create_time <= #{endDate}
        

        
            and r.confirm_time >= #{startDate}
        

        
            and r.confirm_time <= #{endDate}
        

        
            and r.apply_date >= #{startDate}
        

        
            and r.apply_date <= #{endDate}
        

        
            and r.project_id = #{projectId}
        

        
            and r.apply_depart_name like concat('%',#{applyDepartName},'%')
        

        
            and r.apply_user_name like concat('%',#{applyUserName},'%')
        

        
            and r.written_by_name like concat('%',#{writtenByName},'%')
        

        
            and r.confirm_status = #{confirmStatus}

select
ifnull(sum(actually_pay_amount),0)
from contract_reimbursement
where bool_delete_enum = 0

    and confirm_status = #{confirmStatus}


    and project_id = #{projectId}

        select
        ifnull(sum(rd.input_tax),0)
        from contract_reimbursement as r,
        contract_reimbursement_detail as rd

        where r.bool_delete_enum = 0
        and rd.bool_delete_enum = 0
        and rd.reimbursement_id = r.id

        
            and r.project_id = #{projectId}
        

        
            and r.confirm_status = #{confirmStatus}
